/* Picking a style used to do NOTHING. Every one of these features needs BOTH
   a selection and a non-zero Amount, and the Amount ships at 0 with nothing to
   seed it — so the chip turned gold, no edit was queued, no pixel moved and no
   message appeared. Measured before this change: 41 of the 51 chip rows in the
   two suites behaved that way, including Makeup style, Brow style, Hair colour
   and every Retouch B eye-makeup row.

   Seeding on first selection is the honest fix: the Amount slider visibly
   moves, so the tap explains itself and the user can dial it back or to zero.
   An amount the user has already set is never overwritten. The file already
   did exactly this inline for mu_flash (||60) and ev_tattoo (||100); this
   generalises it rather than repeating it 41 times. */
var ST_SEED_AMT=60;
/* The same trap one level down. These sliders are children of a master that
   ships at 0, and their calc() bails out while it stays there — so dragging
   "— Freckle" turned its readout gold, queued nothing, moved no pixel and left
   the group's dirty dot at 0. Twelve sliders behaved that way; the user was
   told an edit had landed when none had.

   Cure as above: move the parent so the child becomes real, and let the parent
   visibly move so the jump explains itself. A parent the user has already set
   is never overwritten. `pick` is for chip parents (choose the first style);
   `t2` is for the one parent that lives in the canvas params. */
var ST_SEED_PARENT={
  ev_freckle:{k:"ev_blemish"},   ev_acne:{k:"ev_blemish"},
  ev_dwFine:{k:"ev_dressWrinkle"}, ev_dwCoarse:{k:"ev_dressWrinkle"},
  ev_ebIris:{t2:"eyeb"}, ev_ebWhites:{t2:"eyeb"},
  ev_ebRefl:{t2:"eyeb"}, ev_ebFlare:{t2:"eyeb"},
  ev_ueLid:{k:"ev_ueDark"},
  st_leakV:{k:"st_leak",pick:"warm"},
  st_frameW:{k:"st_frame",pick:"thin"}
};
function stSeedParent(childId,featId){
  var p=ST_SEED_PARENT[childId];
  if(p){
    if(p.t2){
      if(state.st.t2[p.t2]) return false;
      state.st.t2[p.t2]=ST_SEED_AMT; return true;
    }
    if(svGet(p.k,null)) return false;
    svSet(p.k,p.pick||ST_SEED_AMT);
    return true;
  }
  /* generalized slider-first seeding, data-driven from the feature's own
     keys: dragging an Amount/Intensity slider whose parent style chip or
     toggle is unset used to queue NOTHING while the readout turned gold —
     the documented "told an edit had landed when none had" failure, fixed
     for chip-first (stSeedAmount) but silent in this direction for every
     unmapped child. Reference parents cannot be seeded and stay excluded. */
  var f=featId&&ST.feats[featId];
  if(!f||!f.keys||f.keys.indexOf(childId)<0) return false;
  var i,k;
  for(i=0;i<f.keys.length;i++){
    k=f.keys[i]; if(k===childId) continue;
    if(svGet(k,null)) return false;            /* a parent is already set */
  }
  for(i=0;i<f.keys.length;i++){
    k=f.keys[i]; if(k===childId) continue;
    if(ST.chipFirst&&ST.chipFirst[k]!=null){ svSet(k,ST.chipFirst[k]); return true; }
    if(ST.togBool&&ST.togBool[k]){ svSet(k,true); return true; }
  }
  return false;
}
function stSeedAmount(featId,pickedId){
  var f=ST.feats[featId]; if(!f||!f.keys) return false;
  for(var i=0;i<f.keys.length;i++){
    var k=f.keys[i];
    if(k===pickedId||!/V$/.test(k)) continue;
    if(svGet(k,0)) return false;        /* the user owns this value — leave it */
    svSet(k,ST_SEED_AMT);
    return true;
  }
  return false;
}
