    var pinned=stPinnedRecipeIdx()===idx;
    var st=el("button","pin"); st.innerHTML=icn(pinned?"i-star-fill":"i-star");
    st.setAttribute("aria-label",L9({my:"House recipe အဖြစ် သတ်မှတ်",en:"Pin as house recipe"}));
    st.title=L9({my:"ပုံအသစ်တိုင်းမှာ အလိုအလျောက်သုံးမယ့် house recipe",en:"Auto-applies to every new photo"});
    st.onclick=function(ev){ ev.stopPropagation(); stPinRecipe(idx); };
    b.appendChild(st);
